# -*- coding: utf-8 -*-
"""أدوات المعايير المحاسبية (IFRS / المعايير السعودية)."""
from biz_tools import F, S, add, CATS, T
N=' ملاحظة: الأداة للتعلّم والتقدير الأولي؛ القياس النهائي يخضع لسياسات منشأتك ومراجعها وللمعيار المعتمد.'

add('ifrs16-lease-calculator','finance','🏢','حاسبة عقود الإيجار IFRS 16','القيمة الحالية لالتزام الإيجار وأصل حق الاستخدام وجدول الإطفاء.',
 [F('p','دفعة الإيجار السنوية','n',120000),F('y','مدة العقد (سنوات)','n',5),F('r','معدل الاقتراض الإضافي %','n',6),F('d','تكاليف مباشرة أولية','n',0),S('t','توقيت الدفعة',[('e','نهاية السنة'),('b','بداية السنة')])],
 r'''function compute(v){const r=v.r/100,n=Math.round(v.y);let pv=0;for(let i=1;i<=n;i++)pv+=v.p/Math.pow(1+r,v.t==='b'?i-1:i);let bal=pv,rows=[],dep=(pv+v.d)/n;for(let i=1;i<=n;i++){let open=bal;if(v.t==='b')bal-=v.p;const int=bal*r;bal+=int;if(v.t==='e')bal-=v.p;rows.push([i,f(open),f(int),f(v.p),f(Math.max(bal,0)),f(dep)])}return kpis([kpi('التزام الإيجار الأولي',f(pv),'good'),kpi('أصل حق الاستخدام',f(pv+v.d)),kpi('إهلاك سنوي',f(dep)),kpi('إجمالي الفوائد',f(v.p*n-pv))])+tbl(['السنة','رصيد أول','فائدة','دفعة','رصيد آخر','إهلاك الأصل'],rows)+'<h4>القيد الأولي</h4>'+tbl(['الحساب','مدين','دائن'],[['أصل حق الاستخدام',f(pv+v.d),''],['التزام الإيجار','',f(pv)],['النقدية (تكاليف أولية)','',f(v.d)]])+rec(['العقود قصيرة الأجل (12 شهرًا فأقل) والأصول منخفضة القيمة يمكن إعفاؤها.','افصح عن الاستحقاقات والتدفقات في الإيضاحات.'])+note(%s)}''' % repr('ملاحظة: للتعلّم والتقدير الأولي؛ القياس النهائي حسب سياسات منشأتك ومراجعها.'))

add('ifrs15-revenue-recognition','finance','🧾','مخطط الاعتراف بالإيراد IFRS 15','توزيع سعر العقد على التزامات الأداء والاعتراف بها بمرور الوقت أو في لحظة.',
 [F('price','سعر العقد الإجمالي','n',100000),F('l','التزامات الأداء (اسم | سعر البيع المستقل | وقت/لحظة | أشهر)','textarea','ترخيص برنامج | 40000 | لحظة | 0\nتنفيذ وتركيب | 30000 | وقت | 6\nدعم سنوي | 30000 | وقت | 12',r=5),F('m','الشهر الحالي منذ البدء','n',3)],
 r'''function compute(v){const L=lines(v.l).map(r=>({n:r[0],s:num(r[1]),k:r[2],m:num(r[3])})),ts=L.reduce((a,x)=>a+x.s,0)||1;const rows=L.map(x=>{const a=v.price*x.s/ts;const rec_=x.k==='لحظة'?a:Math.min(a,a*(v.m/(x.m||1)));return[x.n,f(x.s),f(a),x.k,f(rec_),f(a-rec_)]});const R=L.map(x=>0);const tot=rows.reduce((a,r)=>a+num(String(r[4]).replace(/,/g,'')),0);return kpis([kpi('سعر العقد',f(v.price)),kpi('إيراد معترف به',f(tot),'good'),kpi('التزام عقد (مؤجل)',f(v.price-tot))])+tbl(['الالتزام','السعر المستقل','المخصص','النمط','معترف به','مؤجل'],rows)+rec(['الخطوات الخمس: عقد، التزامات، سعر، توزيع، اعتراف.','وزّع السعر نسبة إلى سعر البيع المستقل لا حسب الفاتورة.'])}''')

add('inventory-valuation-ias2','finance','📦','تقييم المخزون IAS 2 (FIFO / متوسط مرجح)','تكلفة المبيعات ومخزون آخر المدة بطريقتين، وصافي القيمة القابلة للتحقق.',
 [F('b','الحركات (نوع شراء/بيع | كمية | سعر للشراء)','textarea','شراء | 100 | 10\nشراء | 150 | 12\nبيع | 180 | 0\nشراء | 50 | 13',r=6),F('nrv','صافي القيمة القابلة للتحقق للوحدة','n',11)],
 r'''function compute(v){const mv=lines(v.b).map(r=>({t:r[0],q:num(r[1]),p:num(r[2])}));let lots=[],cogsF=0,q=0,val=0,cogsW=0;mv.forEach(m=>{if(m.t==='شراء'){lots.push({q:m.q,p:m.p});q+=m.q;val+=m.q*m.p}else{let need=m.q;const avg=q?val/q:0;cogsW+=need*avg;q-=need;val-=need*avg;while(need>0&&lots.length){const l=lots[0],t=Math.min(l.q,need);cogsF+=t*l.p;l.q-=t;need-=t;if(l.q<=0)lots.shift()}}});const endF=lots.reduce((a,l)=>a+l.q*l.p,0),uF=lots.reduce((a,l)=>a+l.q,0),endW=val;const lw=Math.min(endF/(uF||1),v.nrv)*uF;return tbl(['الطريقة','تكلفة المبيعات','مخزون آخر المدة'],[['FIFO',f(cogsF),f(endF)],['المتوسط المرجح',f(cogsW),f(endW)]])+kpis([kpi('وحدات متبقية',f(uF,0)),kpi('FIFO بعد NRV',f(lw),lw<endF?'bad':'good'),kpi('تخفيض لـ NRV',f(Math.max(0,endF-lw)))])+rec(['المخزون يُقاس بالأقل من التكلفة وNRV.','LIFO غير مسموح في IAS 2.','الطريقة تُطبّق باتساق على الأصناف المتشابهة.'])}''')

add('ifrs9-ecl-matrix','finance','📉','مصفوفة الخسائر الائتمانية المتوقعة IFRS 9','مخصص الديون المشكوك فيها بمنهج مصفوفة التقادم.',
 [F('a','فئات التقادم (الفئة | الرصيد | نسبة الخسارة %)','textarea','جاري | 500000 | 0.5\n1-30 يوم | 200000 | 2\n31-60 يوم | 100000 | 8\n61-90 يوم | 60000 | 20\n أكثر من 90 | 40000 | 50',r=6),F('c','مخصص قائم','n',15000)],
 r'''function compute(v){const rows=lines(v.a).map(r=>{const b=num(r[1]),p=num(r[2]);return[r[0],f(b),p+'%',f(b*p/100)]});const tb=lines(v.a).reduce((a,r)=>a+num(r[1]),0),te=lines(v.a).reduce((a,r)=>a+num(r[1])*num(r[2])/100,0);rows.push(['الإجمالي',f(tb),f(te/tb*100,2)+'%',f(te)]);const ch=te-v.c;return tbl(['الفئة','الرصيد','النسبة','الخسارة المتوقعة'],rows)+kpis([kpi('المخصص المطلوب',f(te),'good'),kpi('المخصص القائم',f(v.c)),kpi(ch>=0?'مصروف إضافي':'استرداد',f(Math.abs(ch)),ch>0?'bad':'good')])+'<h4>القيد</h4>'+tbl(['الحساب','مدين','دائن'],[[ch>=0?'مصروف خسائر ائتمانية':'مخصص خسائر ائتمانية',f(Math.abs(ch)),''],[ch>=0?'مخصص خسائر ائتمانية':'استرداد مخصص','',f(Math.abs(ch))]])+rec(['عدّل النسب التاريخية بمعلومات مستقبلية (اقتصاد، قطاع).','راجع المصفوفة سنويًا على الأقل.'])}''')

add('ias36-impairment-test','finance','🧱','اختبار الانخفاض في القيمة IAS 36','قارن القيمة الدفترية بالمبلغ القابل للاسترداد واحسب خسارة الانخفاض.',
 [F('cv','القيمة الدفترية للأصل/الوحدة','n',900000),F('fv','القيمة العادلة ناقص تكاليف البيع','n',700000),F('cf','التدفق النقدي السنوي المتوقع','n',150000),F('y','سنوات التدفق','n',8),F('r','معدل الخصم %','n',10)],
 r'''function compute(v){const r=v.r/100;let viu=0;for(let i=1;i<=v.y;i++)viu+=v.cf/Math.pow(1+r,i);const rec_=Math.max(viu,v.fv),loss=Math.max(0,v.cv-rec_);return kpis([kpi('القيمة الاستخدامية',f(viu)),kpi('القيمة العادلة - بيع',f(v.fv)),kpi('القابل للاسترداد',f(rec_)),kpi('خسارة الانخفاض',f(loss),loss>0?'bad':'good')])+(loss>0?'<h4>القيد</h4>'+tbl(['الحساب','مدين','دائن'],[['خسارة انخفاض في القيمة',f(loss),''],['مجمع الانخفاض في الأصل','',f(loss)]]):'<b>لا انخفاض: القيمة القابلة للاسترداد أعلى من الدفترية.</b>')+rec(['المبلغ القابل للاسترداد هو الأعلى من القيمة الاستخدامية والعادلة ناقص البيع.','الشهرة تُختبر سنويًا.','يجوز عكس الخسارة لغير الشهرة بشروط.'])}''')

add('depreciation-ias16','finance','🏗️','حاسبة الإهلاك IAS 16 (بطرق متعددة)','القسط الثابت والمتناقص ووحدات الإنتاج مع جدول سنوي.',
 [F('c','تكلفة الأصل','n',100000),F('s','القيمة التخريدية','n',10000),F('y','العمر الإنتاجي (سنوات)','n',5),S('m','الطريقة',[('sl','القسط الثابت'),('db','القسط المتناقص (ضعف)'),('syd','مجموع سنوات الاستخدام')])],
 r'''function compute(v){const n=Math.round(v.y),d=v.c-v.s;let bv=v.c,acc=0,rows=[];const syd=n*(n+1)/2;for(let i=1;i<=n;i++){let x;if(v.m==='sl')x=d/n;else if(v.m==='db'){x=Math.min(bv*2/n,bv-v.s);x=Math.max(x,0)}else x=d*(n-i+1)/syd;acc+=x;bv-=x;rows.push([i,f(x),f(acc),f(bv)])}return kpis([kpi('القابل للإهلاك',f(d)),kpi('إهلاك السنة الأولى',f(rows[0]?num(rows[0][1].replace(/,/g,'')):0))])+tbl(['السنة','الإهلاك','مجمع','القيمة الدفترية'],rows)+rec(['راجع العمر والقيمة التخريدية سنويًا.','المكونات المهمة تُهلك منفصلة.'])}''')

add('ias12-deferred-tax','finance','🏛️','حاسبة الضريبة المؤجلة IAS 12','الفروق المؤقتة والأصل/الالتزام الضريبي المؤجل.',
 [F('t','الأصول: القيمة الدفترية المحاسبية','n',500000),F('b','الأساس الضريبي للأصل','n',380000),F('r','معدل الضريبة %','n',20),F('p','رصيد ضريبة مؤجلة سابق (التزام)','n',15000)],
 r'''function compute(v){const diff=v.t-v.b,dt=diff*v.r/100,ch=dt-v.p;return kpis([kpi('الفرق المؤقت الخاضع للضريبة',f(diff)),kpi('التزام ضريبي مؤجل',f(dt),'bad'),kpi('التغير للفترة',f(ch))])+'<h4>القيد</h4>'+tbl(['الحساب','مدين','دائن'],[[ch>=0?'مصروف ضريبة مؤجلة':'التزام ضريبي مؤجل',f(Math.abs(ch)),''],[ch>=0?'التزام ضريبي مؤجل':'ايراد ضريبة مؤجلة','',f(Math.abs(ch))]])+rec(['الدفتري > الضريبي يعني فرقًا خاضعًا للضريبة (التزام).','الأصل الضريبي المؤجل يشترط احتمال أرباح مستقبلية كافية.'])}''')

add('effective-interest-bond','finance','🪙','جدول إطفاء السندات والقروض (الفائدة الفعلية)','IFRS 9: التكلفة المطفأة بمعدل الفائدة الفعلي.',
 [F('f','القيمة الاسمية','n',1000000),F('c','معدل القسيمة %','n',5),F('m','معدل السوق (الفعلي) %','n',7),F('y','المدة (سنوات)','n',5)],
 r'''function compute(v){const n=Math.round(v.y),cp=v.f*v.c/100,r=v.m/100;let pv=v.f/Math.pow(1+r,n);for(let i=1;i<=n;i++)pv+=cp/Math.pow(1+r,i);let bal=pv,rows=[];for(let i=1;i<=n;i++){const int=bal*r,am=int-cp;bal+=am;rows.push([i,f(int),f(cp),f(am),f(bal)])}return kpis([kpi('سعر الإصدار',f(pv)),kpi(pv<v.f?'خصم إصدار':'علاوة إصدار',f(Math.abs(v.f-pv)))])+tbl(['السنة','مصروف الفائدة','القسيمة','الإطفاء','الرصيد'],rows)+rec(['إذا كان معدل السوق أعلى من القسيمة فالسعر بخصم.'])}''')

add('financial-ratios-analyzer','finance','📊','محلل النسب المالية','سيولة ونشاط وربحية ومديونية من أرقام قوائمك.',
 [F('ca','أصول متداولة','n',600000),F('cl','التزامات متداولة','n',350000),F('inv','مخزون','n',200000),F('rev','الإيرادات','n',2000000),F('np','صافي الربح','n',180000),F('ta','إجمالي الأصول','n',1500000),F('td','إجمالي الديون','n',700000),F('eq','حقوق الملكية','n',800000),F('cogs','تكلفة المبيعات','n',1300000)],
 r'''function compute(v){const R=[['نسبة التداول',v.ca/v.cl,'≥ 1.5'],['النسبة السريعة',(v.ca-v.inv)/v.cl,'≥ 1'],['هامش مجمل الربح %',(v.rev-v.cogs)/v.rev*100,'حسب القطاع'],['هامش صافي الربح %',v.np/v.rev*100,'حسب القطاع'],['العائد على الأصول %',v.np/v.ta*100,'—'],['العائد على الملكية %',v.np/v.eq*100,'—'],['الدين إلى الملكية',v.td/v.eq,'≤ 1.5'],['دوران الأصول',v.rev/v.ta,'—'],['دوران المخزون',v.cogs/v.inv,'—'],['أيام المخزون',365/(v.cogs/v.inv),'—']];return tbl(['النسبة','القيمة','مرجع'],R.map(r=>[r[0],f(r[1],2),r[2]]))+rec([v.ca/v.cl<1?'السيولة ضعيفة: تعثر محتمل في السداد قصير الأجل.':'السيولة مقبولة.',v.td/v.eq>2?'الاعتماد على الدين مرتفع.':'المديونية معتدلة.','قارن النسب بمتوسط القطاع وباتجاه السنوات.'])+aiOut('حلّل النسب المالية التالية واقترح 5 إجراءات: '+R.map(r=>r[0]+'='+f(r[1],2)).join('، '))}''')

add('ias33-eps-calculator','finance','🧮','حاسبة ربحية السهم IAS 33','الأساسية والمخفضة مع المتوسط المرجح للأسهم.',
 [F('np','صافي ربح المساهمين العاديين','n',900000),F('s','الأسهم أول السنة','n',1000000),F('i','أسهم مصدرة خلال السنة','n',200000),F('mo','أشهر منذ الإصدار','n',4),F('d','أسهم محتملة مخفضة (خيارات/تحويل)','n',100000),F('di','أرباح تحويل تُضاف (بعد الضريبة)','n',0)],
 r'''function compute(v){const w=v.s+v.i*v.mo/12,eps=v.np/w,deps=(v.np+v.di)/(w+v.d);return kpis([kpi('المتوسط المرجح للأسهم',f(w,0)),kpi('ربحية السهم الأساسية',f(eps,3),'good'),kpi('ربحية السهم المخفضة',f(deps,3)),kpi('الأثر المخفِّف',f((1-deps/eps)*100,1)+'%')])+rec(['الأدوات المخففة تُدرج فقط إن خفّضت ربحية السهم.','تُعرض الأساسية والمخفضة في قائمة الدخل.'])}''')

add('journal-entry-generator-ifrs','finance','📒','مولّد قيود يومية للعمليات الشائعة','اختر نوع العملية وأدخل المبلغ لتحصل على القيد والمعيار المرتبط.',
 [S('k','العملية',[('sale','بيع آجل'),('purchase','شراء مخزون نقدًا'),('depr','إهلاك شهري'),('accr','مصروف مستحق'),('prepaid','مصروف مدفوع مقدمًا'),('bad','مخصص ديون مشكوك فيها'),('salary','رواتب مستحقة'),('vat','ضريبة قيمة مضافة على مبيعات')]),F('a','المبلغ','n',10000),F('v','نسبة الضريبة %','n',15)],
 r'''function compute(v){const a=v.a,t=a*v.v/100;const M={sale:[['ذمم مدينة',a,0],['إيراد مبيعات',0,a],['تكلفة المبيعات / المخزون','حسب النظام',''],'IFRS 15'],purchase:[['المخزون',a,0],['النقدية',0,a],'IAS 2'],depr:[['مصروف إهلاك',a,0],['مجمع الإهلاك',0,a],'IAS 16'],accr:[['مصروف',a,0],['مصروفات مستحقة',0,a],'مبدأ الاستحقاق'],prepaid:[['مصروف مدفوع مقدمًا',a,0],['النقدية',0,a],'مبدأ الاستحقاق'],bad:[['مصروف خسائر ائتمانية',a,0],['مخصص خسائر ائتمانية',0,a],'IFRS 9'],salary:[['مصروف رواتب',a,0],['رواتب مستحقة',0,a],'IAS 19'],vat:[['ذمم مدينة',a+t,0],['إيراد مبيعات',0,a],['ضريبة قيمة مضافة مستحقة',0,t],'ضريبة القيمة المضافة']}[v.k];const std=M[M.length-1];const rows=M.slice(0,-1).map(r=>[r[0],r[1]===0?'':(typeof r[1]==='number'?f(r[1]):r[1]),r[2]===0?'':(typeof r[2]==='number'?f(r[2]):r[2])]);return tbl(['الحساب','مدين','دائن'],rows)+kpis([kpi('المعيار/المبدأ',std)])+rec(['راجع قيدك مع دليل حساباتك.','وثّق العملية بمستند.'])}''')

add('accounting-standards-finder','finance','🔍','دليل المعايير المحاسبية: أي معيار ينطبق؟','اكتب العملية أو الموضوع لتعرف المعيار الدولي (IFRS/IAS) المرتبط.',
 [F('q','الموضوع أو العملية','text','عقد إيجار سيارات لخمس سنوات')],
 r'''function compute(v){const D=[['إيجار|تأجير|ايجار','IFRS 16 عقود الإيجار'],['إيراد|مبيعات|عقد مع عميل','IFRS 15 الإيراد من العقود مع العملاء'],['مخزون|بضاعة','IAS 2 المخزون'],['أصول ثابتة|إهلاك|معدات','IAS 16 العقارات والمصانع والمعدات'],['أصول غير ملموسة|برمجيات|براءة|علامة','IAS 38 الأصول غير الملموسة'],['انخفاض|هبوط في القيمة','IAS 36 انخفاض قيمة الأصول'],['أدوات مالية|ذمم|ديون مشكوك|قرض|استثمار','IFRS 9 الأدوات المالية'],['ضريبة مؤجلة|ضريبة دخل','IAS 12 ضرائب الدخل'],['مكافأة نهاية|رواتب|منافع موظفين','IAS 19 منافع الموظفين'],['مخصصات|التزام محتمل|قضية','IAS 37 المخصصات والالتزامات المحتملة'],['ربحية السهم|أسهم','IAS 33 ربحية السهم'],['دمج|استحواذ|شراء شركة','IFRS 3 تجميع الأعمال'],['قوائم موحدة|شركة تابعة|سيطرة','IFRS 10 القوائم المالية الموحدة'],['تدفقات نقدية','IAS 7 قائمة التدفقات النقدية'],['عملة أجنبية|صرف','IAS 21 أسعار الصرف'],['استثمار عقاري','IAS 40 العقارات الاستثمارية'],['أحداث بعد|لاحقة','IAS 10 الأحداث بعد فترة التقرير'],['إفصاح|أطراف ذات علاقة','IAS 24 الإفصاح عن الأطراف ذات العلاقة'],['منح حكومية|دعم حكومي','IAS 20 المنح الحكومية'],['تكاليف اقتراض|رسملة','IAS 23 تكاليف الاقتراض'],['قطاعات تشغيل','IFRS 8 القطاعات التشغيلية'],['سياسات|أخطاء|تغير تقدير','IAS 8 السياسات المحاسبية والتقديرات والأخطاء']];const q=v.q;const hits=D.filter(d=>new RegExp(d[0]).test(q)).map(d=>[d[1]]);return (hits.length?tbl(['المعيار المقترح'],hits):'<b>لا تطابق مباشر: جرّب كلمات أبسط مثل «إيراد» أو «مخزون» أو «إيجار».</b>')+rec(['المعايير السعودية الحالية هي المعايير الدولية المعتمدة من الهيئة السعودية للمراجعين والمحاسبين (SOCPA) مع معيار للمنشآت الصغيرة والمتوسطة.','راجع نص المعيار الأصلي قبل التطبيق.'])+aiOut('اشرح معالجة هذه العملية محاسبيًا وفق المعايير الدولية مع قيد يومي وإفصاحات: '+q)}''')

add('provisions-ias37','finance','⚠️','مقيّم المخصصات IAS 37','هل تعترف بمخصص أم تفصح عن التزام محتمل؟',
 [S('p','التزام حالي نتيجة حدث سابق؟',[('1','نعم'),('0','لا')]),S('o','احتمال تدفق خارج للموارد',[('h','محتمل (أكثر من 50%)'),('m','ممكن (أقل من 50%)'),('r','بعيد')]),S('e','هل يمكن تقدير المبلغ بموثوقية؟',[('1','نعم'),('0','لا')]),F('a','المبلغ المقدّر','n',80000)],
 r'''function compute(v){let d,c;if(v.p==='0'){d='لا مخصص: لا التزام حالي.';c='good'}else if(v.o==='h'&&v.e==='1'){d='اعترف بمخصص بمبلغ '+f(v.a);c='bad'}else if(v.o==='h'){d='أفصح عن التزام محتمل لعدم إمكان التقدير.';c=''}else if(v.o==='m'){d='أفصح عن التزام محتمل.';c=''}else{d='لا حاجة لإفصاح (احتمال بعيد).';c='good'}return kpis([kpi('القرار',d,c)])+(d.startsWith('اعترف')?'<h4>القيد</h4>'+tbl(['الحساب','مدين','دائن'],[['مصروف مخصص',f(v.a),''],['مخصص التزامات','',f(v.a)]]):'')+rec(['المخصص يقاس بأفضل تقدير للمبلغ اللازم للتسوية.','راجع المخصصات في كل تاريخ تقرير.'])}''')
